syntax:
class ClassName {
    static ReturnType FunctionName(Parameters); 
};

// Definition outside class
ReturnType ClassName::FunctionName(Parameters) { /* ... */ }

code_example:
#include <iostream>
class LocaleManager {
public:
    static void setGlobalLocale(const std::string& loc) {
        globalLocale = loc;
        std::cout << "Global locale set to: " << globalLocale << std::endl;
    }
private:
    static std::string globalLocale;
};
std::string LocaleManager::globalLocale = "en_US.UTF-8";

int main() {
    // Call static member function without creating an instance
    LocaleManager::setGlobalLocale("fr_FR.UTF-8");
    return 0;
}
